"use client";
import { Switch, useFujiConfig } from "@fujiui/react";

export function DarkModeSwitch() {
  const { theme, setTheme } = useFujiConfig();
  return (
    <Switch
      label="Dark mode"
      checked={theme === "dark"}
      onCheckedChange={(on) => setTheme(on ? "dark" : "light")}
    />
  );
}

"use client";
import * as React from "react";
import { FujiProvider, type FujiTheme } from "@fujiui/react";

const query = "(prefers-color-scheme: dark)";
const subscribe = (onChange: () => void) => {
  const list = window.matchMedia(query);
  list.addEventListener("change", onChange);
  return () => list.removeEventListener("change", onChange);
};

function useSystemTheme(): FujiTheme {
  return React.useSyncExternalStore(
    subscribe,
    () => (window.matchMedia(query).matches ? "dark" : "light"),
    () => "light",
  );
}

export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <FujiProvider theme={useSystemTheme()} className="min-h-dvh">
      {children}
    </FujiProvider>
  );
}

// app/layout.tsx (Next.js)
import Script from "next/script";
import "@fujiui/react/styles.css";
import { buildAppearanceBootstrapScript, FujiProvider } from "@fujiui/react";

const DEFAULTS = { theme: "light", material: "solid", radius: "cornered", elevation: "regular" } as const;
const BOOTSTRAP = buildAppearanceBootstrapScript(DEFAULTS);

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" data-fuji-boot="" suppressHydrationWarning>
      <head>
        <Script id="fuji-appearance" strategy="beforeInteractive" dangerouslySetInnerHTML={{ __html: BOOTSTRAP }} />
      </head>
      <body>
        <FujiProvider persist defaultTheme={DEFAULTS.theme} defaultMaterial={DEFAULTS.material} className="min-h-dvh">
          {children}
        </FujiProvider>
      </body>
    </html>
  );
}

/* app/globals.css - Tailwind v4 */
@layer properties, theme, base, fuji, components, utilities;
@import "tailwindcss";
@import "@fujiui/react/styles.css";

/* dark: follows FujiProvider's theme, not the OS */
@custom-variant dark (&:where([data-fuji-theme=dark], [data-fuji-theme=dark] *));

@theme inline {
  --color-fuji-background: var(--fuji-background);
  --color-fuji-surface: var(--fuji-surface);
  --color-fuji-foreground: var(--fuji-foreground);
  --color-fuji-foreground-muted: var(--fuji-foreground-muted);
  --color-fuji-border: var(--fuji-border);
}
